mapper.select:
SELECT 
  FROM PET_PRTC_MTCH T
 WHERE T.PET_PRTC_MTCH_SN = #{petPrtcMtchSn}

mapper.update:
UPDATE PET_PRTC_MTCH
   SET MTCH_DLNG_STTS_CD = #{aftrSttsCd}
     , MDFCN_DT = NOW()
 WHERE PET_PRTC_MTCH_SN = #{petPrtcMtchSn}
   AND MTCH_DLNG_STTS_CD = #{bfrSttsCd}

UPDATE PET_PRTC_MTCH
   SET MTCH_DLNG_STTS_CD = #{requestedCd}
     , IDMPT_DMND_ID = #{idmptDmndId}
     , RCV_YN = NULL
     , RCV_IDNTY_DT = NULL
     , MDFCN_DT = NOW()
 WHERE PET_PRTC_MTCH_SN = #{petPrtcMtchSn}
   AND MTCH_DLNG_STTS_CD = #{canceledCd}

UPDATE PET_PRTC_MTCH
   SET RCV_YN = #{rcvYn}
     , RCV_IDNTY_DT = NOW()
     , MDFCN_DT = NOW()
 WHERE PET_PRTC_MTCH_SN = #{petPrtcMtchSn}

mapper.insert:
